import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.I6s8z2kk.js";const g=JSON.parse('{"title":"Getting around the admin panel","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/getting-around.md","filePath":"user/admin/getting-around.md"}'),r={name:"user/admin/getting-around.md"};function o(i,e,d,h,c,l){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="getting-around-the-admin-panel" tabindex="-1">Getting around the admin panel <a class="header-anchor" href="#getting-around-the-admin-panel" aria-label="Permalink to &quot;Getting around the admin panel&quot;">​</a></h1><p>The admin panel is for platform staff (<strong>system users</strong>). What you can see and do depends on the <strong>role</strong> you were given. If a section is missing or an action is refused, ask an administrator to check your role.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Sign in with your email and password. Inactive users cannot sign in.</p><h2 id="what-you-can-manage" tabindex="-1">What you can manage <a class="header-anchor" href="#what-you-can-manage" aria-label="Permalink to &quot;What you can manage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Page</th></tr></thead><tbody><tr><td>Centers, their services, reservations and purchases</td><td><a href="./centers">Centers</a></td></tr><tr><td>Client accounts</td><td><a href="./clients">Clients</a></td></tr><tr><td>Discounts, campaigns and coupons</td><td><a href="./promotions">Promotions</a></td></tr><tr><td>What clients see first in the app</td><td><a href="./homepage">Homepage</a></td></tr><tr><td>Push and WhatsApp messages</td><td><a href="./notifications">Notifications</a></td></tr><tr><td>Plans and center subscriptions</td><td><a href="./billing">Plans and subscriptions</a></td></tr><tr><td>Fees, payments and center payouts</td><td><a href="./payments-payouts">Purchases, fees and payouts</a></td></tr><tr><td>Dashboards and spreadsheets</td><td><a href="./analytics">Analytics and exports</a></td></tr><tr><td>Staff accounts, roles, cities and tags</td><td><a href="./users-roles">Users and roles</a></td></tr></tbody></table><h2 id="legal-pages" tabindex="-1">Legal pages <a class="header-anchor" href="#legal-pages" aria-label="Permalink to &quot;Legal pages&quot;">​</a></h2><p><strong>Settings → Legal pages</strong> holds the privacy policy and terms and conditions of the client app and of the center app, each in English and Arabic. Write them in the editor (headings, lists, links, alignment) and <strong>Save</strong>; both languages are required. The apps open the published page right away. Use <strong>Open page</strong> to see it as clients and centers do. You need the <strong>Legal documents</strong> permission (<code>legal_documents.manage</code>).</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>The bell shows platform events (for example a new center registering). Mark one or all as read. Allow browser notifications when the panel asks to also get them as pop-ups while the panel is closed or in the background; signing out stops them on that browser.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>The search box in the top bar finds a record anywhere in the panel. Click it, or press <strong>⌘K</strong> (Mac) or <strong>Ctrl+K</strong>, and type at least two characters: a center name, phone or email; a client&#39;s name or phone; a service name; or the 6-character code of a reservation or purchase. Results are grouped into centers, clients, reservations, purchases, client packages, client memberships and services, with up to five per group. Pick one to open it. You only see the groups your role allows.</p><h2 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h2><p>Lists are paged and can be searched and filtered. Large lists can be exported to a spreadsheet; see <a href="./analytics">Analytics and exports</a>.</p><p>On the centers, clients, purchases, subscriptions, payouts and center ledger lists, a column header with arrows can be clicked to sort by it: once for ascending, again for descending, and a third time to go back to newest first. The sort stays when you change filters, and exports keep the same order.</p><h2 id="the-documentation" tabindex="-1">The documentation <a class="header-anchor" href="#the-documentation" aria-label="Permalink to &quot;The documentation&quot;">​</a></h2><p>Staff with the <strong>API docs</strong> permission can also open these guides and the technical endpoint reference. Use <strong>Sign out</strong> in the top bar when you are done.</p>',17)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
